import{_ as t,o,c as d,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"主题系统实现","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/theme-system.md","filePath":"advanced/theme-system.md","lastUpdated":1792319529000}'),c={name:"advanced/theme-system.md"};function r(s,e,l,i,n,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="主题系统实现" tabindex="-1">主题系统实现 <a class="header-anchor" href="#主题系统实现" aria-label="Permalink to &quot;主题系统实现&quot;">​</a></h1><p>主题系统的内部运作：状态模型、颜色如何从单个种子色派生、玻璃效果由哪些 CSS 变量驱动，以及自定义背景下文字颜色如何自动调整。</p><h2 id="状态模型-themestore" tabindex="-1">状态模型（themeStore） <a class="header-anchor" href="#状态模型-themestore" aria-label="Permalink to &quot;状态模型（themeStore）&quot;">​</a></h2><p><code>themeStore</code> 是基于 zustand 的仓库，通过 persist 中间件把全部主题状态持久化到 localStorage，key 为 <strong><code>zcontrol-theme-storage</code></strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>sourceColor</code></td><td><code>#0066cc</code></td><td>Monet 种子色</td></tr><tr><td><code>mode</code></td><td><code>&#39;light&#39;</code></td><td><code>auto / light / dark</code>；<code>isDark</code> 是其物化值</td></tr><tr><td><code>colorIntensity</code></td><td><code>100</code></td><td>种子色与中性基底的混合比例</td></tr><tr><td><code>radius</code></td><td><code>&#39;medium&#39;</code></td><td>预设 none 0 / small 8 / medium 16 / large 28 px</td></tr><tr><td><code>glassStrength</code> / <code>glassBlur</code></td><td><code>0.6</code> / <code>12</code></td><td>玻璃透明度 / 模糊度</td></tr><tr><td><code>backgroundImage</code></td><td><code>null</code></td><td>URL 或 base64 dataURL（上传限 5MB）</td></tr><tr><td><code>backgroundBlur</code> / <code>listenTogetherBlur</code></td><td><code>13</code> / <code>0</code></td><td>通用背景模糊 / 一起听独立模糊</td></tr><tr><td><code>backgroundWhiteOverlay</code> / <code>BlackOverlay</code></td><td><code>0</code></td><td>白 / 黑遮罩强度</td></tr><tr><td><code>customColors</code></td><td><code>[]</code></td><td>收藏色板，上限 24 条</td></tr></tbody></table><p>切换深浅色请调用 <code>setMode</code> 或 <code>setDark</code>，不要直接 <code>set({isDark})</code>——<code>isDark</code> 由 <code>mode</code> 派生（<code>auto</code> 时由 matchMedia 物化），直接写会破坏 <code>mode</code> 一致性。</p><h3 id="auto-模式物化" tabindex="-1">auto 模式物化 <a class="header-anchor" href="#auto-模式物化" aria-label="Permalink to &quot;auto 模式物化&quot;">​</a></h3><p><code>mode === &#39;auto&#39;</code> 时 ThemeProvider 监听 <code>(prefers-color-scheme: dark)</code> 的 change 事件，变化即 <code>setState({ isDark })</code>；消费方只读 <code>isDark</code>。非 auto 模式不挂该监听。</p><h2 id="material-you-动态主题" tabindex="-1">Material You 动态主题 <a class="header-anchor" href="#material-you-动态主题" aria-label="Permalink to &quot;Material You 动态主题&quot;">​</a></h2><p>种子色交给 <code>@material/material-color-utilities</code> 的 <code>themeFromSourceColor</code>，生成浅色与深色两套方案：每套输出 27 个 <code>--md-sys-color-*</code> 角色、surface-container 三档（深色 12/17/22、浅色 94/92/90）与 primary/secondary/tertiary 色阶（13 档 tone）。两套方案按「种子色 + 强度」记忆化缓存供对比度判定复用；非法 hex 回退默认方案。</p><h2 id="颜色强度" tabindex="-1">颜色强度 <a class="header-anchor" href="#颜色强度" aria-label="Permalink to &quot;颜色强度&quot;">​</a></h2><p>强度控制种子色与中性基底在 sRGB 空间的逐通道插值（与 <code>color-mix(in srgb)</code> 同义）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SEED_MIX_BASE = { light: &#39;#f3f1f7&#39;, dark: &#39;#17161b&#39; }</span></span>\n<span class="line"><span>effectiveSeed = mix(seed, base, intensity / 100)</span></span></code></pre></div><p>强度为 100 时直接返回纯种子色（默认值，与未引入强度功能时一致）。浅色与深色各用自己的基底合成，低强度下派生色仍与背景协调。</p><h2 id="文字对比度自适应" tabindex="-1">文字对比度自适应 <a class="header-anchor" href="#文字对比度自适应" aria-label="Permalink to &quot;文字对比度自适应&quot;">​</a></h2><p>自定义背景与玻璃面板各有底色，单一全局判定无法覆盖，因此分成三个作用域的 CSS 变量：</p><table tabindex="0"><thead><tr><th>变量组</th><th>判定依据</th><th>消费方</th></tr></thead><tbody><tr><td>根节点（无作用域）</td><td>scheme 原生值，<strong>永不切换</strong></td><td>弹窗（portal 到 body）、硬编码色组件</td></tr><tr><td><code>--lt-raw-*</code></td><td>原始背景（底色 → 壁纸 → 遮罩）</td><td>音乐壳等文字直坐壁纸的页面</td></tr><tr><td><code>--lt-glass-*</code></td><td>含玻璃层的有效背景（<code>surface-container × glassStrength</code>）</td><td>顶栏、播放页、迷你条等玻璃面</td></tr></tbody></table><h3 id="合成算法-bgcontrast-ts" tabindex="-1">合成算法（<code>bgContrast.ts</code>） <a class="header-anchor" href="#合成算法-bgcontrast-ts" aria-label="Permalink to &quot;合成算法（`bgContrast.ts`）&quot;">​</a></h3><p>按 UI 渲染顺序在 sRGB 空间逐通道叠加：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>底色 → 壁纸（opacity 混合，32×32 canvas 降采样平均色） → 白遮罩 → 黑遮罩 → 玻璃面板层</span></span></code></pre></div><ul><li>壁纸平均色用 32×32 canvas（<code>willReadFrequently</code>）求均值，结果按 URL 缓存（含失败）。高斯模糊不改变平均亮度，不触发重采样。</li><li>玻璃层必须计入：深色模式的深玻璃会压暗文字底色，不计入会误判。</li><li>切换规则：对侧 scheme 文字色的对比度需比当前侧<strong>高出 1.0</strong> 才切换，避免临界点抖动。覆盖变量仅四个中性文字色：<code>on-surface / on-surface-variant / outline / outline-variant</code>。</li></ul><h2 id="主题编辑栏" tabindex="-1">主题编辑栏 <a class="header-anchor" href="#主题编辑栏" aria-label="Permalink to &quot;主题编辑栏&quot;">​</a></h2><p>主题菜单打开后一级左栏即展开；Zen 主题编辑器分五段：模式切换（auto ✨ / 浅色 ☀ / 深色 🌙）、取色页（SV 二维区 + 色相条 + Hex）、颜色强度滑块、预设 10 色网格 + 收藏色板、实时预览。</p><p>收藏色板遵循单向数据流：</p><ul><li>点击圆点表示应用该颜色，只切换，不触碰色板。</li><li>取色页的「收藏」为新增，「更新收藏」为原位更新被编辑条目（仅从收藏色进入取色页时出现）；当前色已在收藏中时两者都禁用。</li><li>🗑 只把颜色移出收藏板，不改变当前主题色。</li></ul><h2 id="玻璃变量与工具类" tabindex="-1">玻璃变量与工具类 <a class="header-anchor" href="#玻璃变量与工具类" aria-label="Permalink to &quot;玻璃变量与工具类&quot;">​</a></h2><p>玻璃拟态由 ThemeProvider 注入的派生变量驱动，组件统一引用 <code>.glass</code> / <code>.glass-strong</code> / <code>.glass-card</code> / <code>.glass-bg</code>。</p><table tabindex="0"><thead><tr><th>变量</th><th>公式</th></tr></thead><tbody><tr><td><code>--glass-blur</code></td><td><code>${glassBlur}px</code></td></tr><tr><td><code>--glass-blur-strong</code></td><td><code>min(40, glassBlur + 4)px</code></td></tr><tr><td><code>--glass-blur-mask</code></td><td><code>glassBlur × 0.4</code>（弹窗蒙层取 40%）</td></tr><tr><td><code>--glass-bg</code></td><td><code>rgba(surface-container-rgb, glassStrength)</code></td></tr><tr><td><code>--glass-border</code></td><td><code>rgba(rgb, min(1, strength + 0.15))</code></td></tr></tbody></table><p><code>:root</code> 中的静态兜底值保证 ThemeProvider 挂载前（如登录卡片首帧）变量已生效。lightningcss 压缩时 <code>-webkit-backdrop-filter</code> 必须写在标准属性之前，否则去重后保留最后一条，Safari 失效。</p><h2 id="哪些写法会破坏毛玻璃" tabindex="-1">哪些写法会破坏毛玻璃 <a class="header-anchor" href="#哪些写法会破坏毛玻璃" aria-label="Permalink to &quot;哪些写法会破坏毛玻璃&quot;">​</a></h2><p>带 <code>transform</code>、<code>filter</code> 的元素会成为 Backdrop Root，落在其内的玻璃层采不到外部背景——这是毛玻璃失效最常见的原因。以下约定来自实际故障复盘：</p><ul><li>入场动画的 <code>animation-fill-mode</code> 一律用 <code>backwards</code>，不要 <code>both</code> / <code>forwards</code>：这两个值会让元素永久保留 <code>transform</code>（封面页毛玻璃丢失即此原因）。只有 exit 动画适合 <code>forwards</code>。</li><li>弹出面板定位不要依赖 <code>transform</code>：用 <code>-translate-x-1/2</code> 居中时 keyframes 会接管 <code>transform</code>，动画期间偏移丢失且结束跳位。改用 <code>left/top</code> 加负 margin、<code>right</code> 定位，或 fixed 定位加数值内联定位并按 placement 覆写 <code>transformOrigin</code>。</li><li><code>filter</code> 同样制造 Backdrop Root：<code>drop-shadow</code> 要分发到子元素，不能写在包含 glass-card 弹窗的容器上（播放队列弹窗模糊丢失即此原因）。</li><li><code>overflow-y-auto</code> 会连带产生 <code>overflow-x: auto</code>，滚动容器会裁掉 absolute 悬出的弹窗；不要让滚动容器包住弹窗锚点，或把弹窗改成 fixed / sheet。</li><li>absolute 背景覆盖层必须加 <code>pointer-events-none</code>，否则会拦截同容器内交互元素的点击。</li><li>滑动条挂 <code>touch-slider</code>（<code>touch-action: none</code>）防止触屏拖动连带滚动；仅 hover 显形的控件挂 <code>lt-touch-visible</code>（<code>pointer: coarse</code> 下常显）。</li></ul><h3 id="精简动画" tabindex="-1">精简动画 <a class="header-anchor" href="#精简动画" aria-label="Permalink to &quot;精简动画&quot;">​</a></h3><p>开关开启时把当前值快照到 <code>_reducedMotionPrev</code>（不持久化）并锁定 <code>glassStrength: 1, glassBlur: 0, backgroundBlur: 0, listenTogetherBlur: 0</code>，关闭时从快照恢复。</p><p><code>[data-reduced-motion=&#39;true&#39;]</code> 挂在 Layout 根容器上裁剪动画；<code>[data-no-hover-transform=&#39;true&#39;]</code> 挂在 <strong>document.body</strong>（portal 组件同样生效），覆盖 Tailwind 的 translate / scale 变量全局关闭 hover 位移。</p><h2 id="自定义背景渲染-layout-tsx" tabindex="-1">自定义背景渲染（Layout.tsx） <a class="header-anchor" href="#自定义背景渲染-layout-tsx" aria-label="Permalink to &quot;自定义背景渲染（Layout.tsx）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>背景层（fixed z-0） → 白遮罩 → 黑遮罩 → 内容层（relative z-auto）</span></span></code></pre></div><ul><li>默认壁纸 <code>/Nacho3.jpg</code>。自定义壁纸 opacity 直接生效，默认壁纸封顶 0.85。</li><li><code>transform</code> 组合顺序固定为 <code>translate(x/2%, y/2%) scale(s) rotate(r)</code>：translate 在前，避免缩放中心扩张抵消偏移；百分比除以 2 把最大偏移限制在 ±50%。位置不用 <code>background-position</code>，因为百分比在 cover 下某方向无溢出时不生效。</li><li>内容层用 <code>z-auto</code> 不创建层叠上下文，glass-card 的 backdrop-filter 才能跨层采样 z-0 背景图。</li><li>模糊值随房间模式切换：<code>roomMode === &#39;listen-together&#39; ? listenTogetherBlur : backgroundBlur</code>。</li></ul>',38)])])}const g=t(c,[["render",r]]);export{p as __pageData,g as default};
